<?php
namespace Sabri\File26;
defined( 'ABSPATH' ) || exit;

/** FR-005 isolated candidate generation, parity verification and atomic connector cutover. */
final class Shadow_Reindex {
	private static $instance;
	private $connectors;
	private $normalizer;
	private $security;
	private $indexer;

	public static function instance( Connectors $connectors = null, Normalizer $normalizer = null, Security $security = null, Indexer $indexer = null ) {
		if ( ! self::$instance && $connectors && $normalizer && $security && $indexer ) { self::$instance = new self( $connectors, $normalizer, $security, $indexer ); }
		return self::$instance;
	}
	private function __construct( Connectors $connectors, Normalizer $normalizer, Security $security, Indexer $indexer ) { $this->connectors=$connectors;$this->normalizer=$normalizer;$this->security=$security;$this->indexer=$indexer; }

	public function boot() {
		remove_action( DB::CRON_QUEUE, array( $this->indexer, 'process_queue' ) );
		add_action( DB::CRON_QUEUE, array( $this, 'process_queue' ), 5 );
		add_action( 'admin_post_sabri_file26_reindex', array( $this, 'admin_reindex' ), 1 );
		add_filter( 'rest_pre_dispatch', array( $this, 'intercept_rest_reindex' ), 5, 3 );
		add_filter( 'sabri_file26_health_extension', array( $this, 'health_extension' ) );
	}

	public function admin_reindex() {
		if ( ! $this->security->can_operate() ) { wp_die( esc_html__( 'Forbidden.', 'sabri-file26' ), '', array( 'response'=>403 ) ); }
		check_admin_referer( 'sabri_file26_reindex' );
		$connector=isset($_POST['connector'])?sanitize_key(wp_unslash($_POST['connector'])):'';
		$job=$this->enqueue($connector,array('mode'=>'full','reason'=>'admin_shadow_reindex'));
		if(is_wp_error($job)){wp_die(esc_html($job->get_error_message()),'',array('response'=>409));}
		wp_safe_redirect(admin_url('admin.php?page=sabri-file26&reindex=shadow-queued&job='.rawurlencode($job)));exit;
	}

	public function intercept_rest_reindex( $result, $server, $request ) {
		if ( ! $request instanceof \WP_REST_Request || '/sabri-search/v1/admin/reindex' !== $request->get_route() || 'POST' !== $request->get_method() ) { return $result; }
		if ( ! $this->security->can_operate() ) { return new \WP_Error( 'file26_forbidden', 'Search operator capability is required.', array( 'status'=>403 ) ); }
		$job=$this->enqueue(sanitize_key((string)$request->get_param('connector')),(array)$request->get_param('scope'));
		return is_wp_error($job)?$job:rest_ensure_response(array('contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'job_uuid'=>$job,'mode'=>'isolated_shadow'));
	}

	public function enqueue( $connector_slug, array $scope = array() ) {
		global $wpdb;$connector_slug=sanitize_key($connector_slug);$connector=$this->connectors->get($connector_slug);
		if(!$connector||!$this->connectors->is_index_eligible($connector_slug)||empty($connector['list_batch'])||!is_callable($connector['list_batch'])){return new \WP_Error('file26_connector_not_reindexable','Connector is not currently eligible for governed shadow reindexing.',array('status'=>409));}
		$scope=$this->scope($scope);$scope['connector']=$connector_slug;$scope['mode']=!empty($scope['mode'])?$scope['mode']:'full';if(!in_array($scope['mode'],array('full','partial'),true)){return new \WP_Error('file26_invalid_reindex_mode','Reindex mode must be full or partial.',array('status'=>400));}
		$scope_json=wp_json_encode($scope);if(false===$scope_json||strlen($scope_json)>8192){return new \WP_Error('file26_invalid_reindex_scope','Shadow reindex scope is invalid or too large.',array('status'=>400));}
		$jobs=DB::table('jobs');$existing=$wpdb->get_var($wpdb->prepare("SELECT job_uuid FROM $jobs WHERE job_type='shadow_reindex_v2' AND status IN ('pending','retry','running') AND scope_json=%s LIMIT 1",$scope_json));if(!empty($wpdb->last_error)){return new \WP_Error('file26_job_read_failed','Current shadow-reindex state could not be read safely.',array('status'=>500));}if($existing){return new \WP_Error('file26_reindex_already_queued','An equivalent governed shadow reindex is already pending or running.',array('status'=>409,'job_uuid'=>$existing));}
		$uuid=DB::uuid();$shadow=$this->shadow_table($uuid);$documents=DB::table('documents');$created=$wpdb->query("CREATE TABLE `$shadow` LIKE `$documents`");if(false===$created){return new \WP_Error('file26_shadow_create_failed','Isolated candidate index could not be created.',array('status'=>500));}
		$ok=$wpdb->insert($jobs,array('job_uuid'=>$uuid,'job_type'=>'shadow_reindex_v2','status'=>'pending','scope_json'=>$scope_json,'cursor_value'=>'','counts_json'=>wp_json_encode(array('processed'=>0,'failed'=>0)),'attempts'=>0,'available_at'=>DB::now(),'created_at'=>DB::now(),'updated_at'=>DB::now()));if(false===$ok){$wpdb->query("DROP TABLE IF EXISTS `$shadow`");return new \WP_Error('file26_job_enqueue_failed','Shadow reindex job could not be queued.',array('status'=>500));}
		$audit=$this->security->audit('shadow_reindex_queued',array('object_type'=>'job','object_key'=>$uuid,'metadata'=>array('connector'=>$connector_slug,'mode'=>$scope['mode'])));if(is_wp_error($audit)){return new \WP_Error('file26_required_audit_failed','Shadow reindex was queued but required audit evidence failed.',array('status'=>500,'mutation_persisted'=>true));}return$uuid;
	}

	public function process_queue() {
		global $wpdb;$jobs=DB::table('jobs');$timeout=max(300,min(DAY_IN_SECONDS,(int)DB::setting('job_lock_timeout_seconds',1800)));$stale=gmdate('Y-m-d H:i:s',time()-$timeout);$now=DB::now();
		$recovered=$wpdb->query($wpdb->prepare("UPDATE $jobs SET status=IF(attempts>=8,'dead_letter','retry'),error_code='worker_timeout',lock_token=NULL,available_at=%s,finished_at=IF(attempts>=8,%s,NULL),updated_at=%s WHERE job_type='shadow_reindex_v2' AND status='running' AND started_at<%s",$now,$now,$now,$stale));if(false===$recovered){return new \WP_Error('file26_job_recovery_failed','Stale shadow workers could not be recovered safely.');}
		$job=$wpdb->get_row("SELECT * FROM $jobs WHERE job_type='shadow_reindex_v2' AND status IN ('pending','retry') AND available_at<=UTC_TIMESTAMP() ORDER BY id ASC LIMIT 1",ARRAY_A);if(null===$job&&!empty($wpdb->last_error)){return new \WP_Error('file26_job_read_failed','Runnable shadow-reindex state could not be read safely.');}if(!$job){return true;}
		$token=hash('sha256',$job['job_uuid'].'|'.microtime(true).'|'.wp_rand());$claimed=$wpdb->query($wpdb->prepare("UPDATE $jobs SET status='running',lock_token=%s,started_at=%s,attempts=attempts+1,updated_at=%s WHERE id=%d AND job_type='shadow_reindex_v2' AND status IN ('pending','retry')",$token,DB::now(),DB::now(),$job['id']));if(false===$claimed){return new \WP_Error('file26_job_claim_failed','Shadow job could not be claimed.');}if(1!==(int)$claimed){return true;}
		$scope=json_decode($job['scope_json'],true);$scope=is_array($scope)?$scope:array();$connector=!empty($scope['connector'])?$this->connectors->get($scope['connector']):null;$attempt=(int)$job['attempts']+1;$shadow=$this->shadow_table($job['job_uuid']);if(!$connector||!$this->connectors->is_index_eligible($scope['connector'])||empty($connector['list_batch'])||!is_callable($connector['list_batch'])){return $this->fail($job,$token,'connector_unavailable',$attempt);}if(!$this->table_exists($shadow)){return $this->fail($job,$token,'shadow_missing',$attempt);}
		try{
			$old_cursor=(string)$job['cursor_value'];$batch=call_user_func($connector['list_batch'],$old_cursor,100,$scope);if(!is_array($batch)||!isset($batch['items'])||!is_array($batch['items'])||count($batch['items'])>100){throw new \RuntimeException('Invalid connector batch.');}$done=!empty($batch['done']);$next=isset($batch['next_cursor'])&&is_scalar($batch['next_cursor'])?substr(sanitize_text_field((string)$batch['next_cursor']),0,512):'';if(!$done&&empty($batch['items'])&&(''===$next||hash_equals($old_cursor,$next))){throw new \RuntimeException('No cursor progress.');}if(!$done&&''===$next){throw new \RuntimeException('Missing continuation cursor.');}
			$counts=json_decode($job['counts_json'],true);$counts=is_array($counts)?$counts:array('processed'=>0,'failed'=>0);$failed=0;foreach($batch['items'] as $item){$r=is_array($item)?$this->stage($shadow,$item,$scope):new \WP_Error('file26_invalid_document','Connector returned a non-document item.');if(is_wp_error($r)){$counts['failed']++;$failed++;}else{$counts['processed']++;}}if($failed){$wpdb->update($jobs,array('counts_json'=>wp_json_encode($counts),'updated_at'=>DB::now()),array('id'=>$job['id'],'lock_token'=>$token));return $this->fail($job,$token,'document_stage_failed',$attempt);}
			if(!$done){$saved=$wpdb->update($jobs,array('status'=>'pending','cursor_value'=>$next,'counts_json'=>wp_json_encode($counts),'lock_token'=>null,'available_at'=>DB::now(),'updated_at'=>DB::now()),array('id'=>$job['id'],'lock_token'=>$token,'status'=>'running'));return 1===(int)$saved?true:new \WP_Error('file26_job_state_write_failed','Shadow reindex progress could not be persisted.');}
			$parity=$this->parity($shadow);if(is_wp_error($parity)){return$this->fail($job,$token,'shadow_parity_read_failed',$attempt);}$expected_count=isset($batch['snapshot_count'])?(int)$batch['snapshot_count']:-1;$expected_checksum=isset($batch['snapshot_checksum'])?strtolower(trim((string)$batch['snapshot_checksum'])):'';if($expected_count<0||!preg_match('/^[a-f0-9]{64}$/',$expected_checksum)){return$this->fail($job,$token,'snapshot_evidence_missing',$attempt);}if($expected_count!==(int)$parity['count']||!hash_equals($expected_checksum,$parity['checksum'])){return$this->fail($job,$token,'snapshot_parity_mismatch',$attempt);}
			$cut=$this->cutover($job,$scope,$shadow,$parity,$token);if(is_wp_error($cut)){return$this->fail($job,$token,'shadow_cutover_failed',$attempt,$cut,false);}
			$counts['shadow_count']=$parity['count'];$counts['shadow_checksum']=$parity['checksum'];$saved=$wpdb->update($jobs,array('status'=>'completed','cursor_value'=>'','counts_json'=>wp_json_encode($counts),'lock_token'=>null,'finished_at'=>DB::now(),'updated_at'=>DB::now()),array('id'=>$job['id'],'lock_token'=>$token,'status'=>'running'));if(1!==(int)$saved){return new \WP_Error('file26_job_state_write_failed','Shadow cutover succeeded but completion state could not be persisted.',array('status'=>500,'cutover_persisted'=>true));}$wpdb->query("DROP TABLE IF EXISTS `$shadow`");return true;
		}catch(\Throwable $e){return$this->fail($job,$token,'job_exception',$attempt);}
	}

	private function stage($shadow,array $source,array $scope){
		global $wpdb;$valid=$this->connectors->validate_document($source);if(is_wp_error($valid)){return$valid;}$d=$this->sanitize_document($source);if(is_wp_error($d)){return$d;}if(!$this->matches_scope($d,$scope)){return new \WP_Error('file26_shadow_scope_violation','Connector returned a document outside the governed shadow-reindex connector or scope.',array('status'=>409));}
		$current=$wpdb->get_var($wpdb->prepare('SELECT object_version FROM '.DB::table('documents').' WHERE canonical_key=%s',$d['canonical_key']));if(!empty($wpdb->last_error)){return new \WP_Error('file26_shadow_active_version_read_failed','Current active derivative version could not be verified.');}if(null!==$current&&(int)$current>(int)$d['object_version']){return new \WP_Error('file26_shadow_source_version_stale','Shadow candidate is older than the active derivative and cannot replace it.',array('status'=>409));}
		$tomb=$wpdb->get_var($wpdb->prepare('SELECT object_version FROM '.DB::table('tombstones').' WHERE canonical_key=%s',$d['canonical_key']));if(!empty($wpdb->last_error)){return new \WP_Error('file26_shadow_tombstone_read_failed','Candidate revocation state could not be verified.');}if(null!==$tomb&&(int)$tomb>(int)$d['object_version']){return new \WP_Error('file26_shadow_source_version_stale','Shadow candidate is older than an authoritative tombstone and cannot replace it.',array('status'=>409));}if(null!==$tomb&&(int)$tomb===(int)$d['object_version']&&$this->is_searchable($d)){return new \WP_Error('file26_shadow_tombstone_precedence','A searchable shadow candidate cannot override an equal-version tombstone.',array('status'=>409));}
		$existing=$wpdb->get_row($wpdb->prepare("SELECT object_version,source_event_sequence,checksum FROM `$shadow` WHERE canonical_key=%s",$d['canonical_key']),ARRAY_A);if(null===$existing&&!empty($wpdb->last_error)){return new \WP_Error('file26_shadow_read_failed','Existing candidate state could not be verified.');}if($existing){if((int)$d['object_version']<(int)$existing['object_version']||((int)$d['object_version']===(int)$existing['object_version']&&(int)$d['source_event_sequence']<(int)$existing['source_event_sequence'])){return true;}if((int)$d['object_version']===(int)$existing['object_version']&&(int)$d['source_event_sequence']===(int)$existing['source_event_sequence']&&!hash_equals((string)$existing['checksum'],(string)$d['checksum'])){return new \WP_Error('file26_event_identity_conflict','Same candidate source identity has conflicting searchable content.');}}
		$sql=$this->upsert_sql($shadow,$d);return false===$wpdb->query($sql)?new \WP_Error('file26_shadow_write_failed','Candidate document or revocation marker could not be staged.'):true;
	}

	/** Keep this projection contract byte-for-byte aligned with Indexer::sanitize_document()/sanitize_payload(); regression enforces parity. */
	private function sanitize_document(array $d){$required=array('connector_slug','domain','object_id','object_version','entity_type','locale','state','visibility','title','canonical_url');foreach($required as $k){if(!isset($d[$k])||''===$d[$k]){return new \WP_Error('file26_invalid_document','Candidate document is missing '.$k);}}$state=sanitize_key($d['state']);$visibility=sanitize_key($d['visibility']);if(!in_array($state,array('published','active','corrected','retracted','restricted','suspended','deleted','private','rejected'),true)||!in_array($visibility,array('public','members','entitled','minor_guarded','restricted'),true)){return new \WP_Error('file26_invalid_visibility_state','Unknown candidate state or visibility.');}$url=$this->security->safe_url($d['canonical_url']);if(!$url){return new \WP_Error('file26_invalid_canonical_url','Candidate canonical URL must be same-origin.');}$connector=sanitize_key($d['connector_slug']);$domain=sanitize_key($d['domain']);$object=substr(sanitize_text_field((string)$d['object_id']),0,191);$title=sanitize_text_field($d['title']);$excerpt=isset($d['excerpt'])?wp_strip_all_tags($d['excerpt'],true):'';$body=isset($d['search_text'])?wp_strip_all_tags($d['search_text'],true):$excerpt;$version=max(1,(int)$d['object_version']);$sequence=isset($d['source_event_sequence'])?max(0,(int)$d['source_event_sequence']):$version;$now=DB::now();$freshness=null;if(!empty($d['freshness_at'])){$ts=strtotime((string)$d['freshness_at']);if(false===$ts){return new \WP_Error('file26_invalid_freshness','Invalid candidate freshness timestamp.');}$freshness=gmdate('Y-m-d H:i:s',$ts);}$payload=$this->safe_payload(isset($d['payload'])&&is_array($d['payload'])?$d['payload']:array());$out=array('canonical_key'=>Indexer::canonical_key($connector,$domain,$object),'connector_slug'=>$connector,'domain_name'=>$domain,'object_id'=>$object,'object_version'=>$version,'entity_type'=>sanitize_key($d['entity_type']),'locale'=>substr(sanitize_text_field($d['locale']),0,20),'state'=>$state,'visibility'=>$visibility,'title'=>$title,'excerpt'=>$excerpt,'normalized_title'=>$this->normalizer->normalize($title),'normalized_body'=>$this->normalizer->normalize($body),'canonical_url'=>$url,'author_key'=>isset($d['author_key'])?substr(sanitize_text_field($d['author_key']),0,191):'','topic_ids'=>wp_json_encode(array_values(array_unique(array_map('sanitize_text_field',isset($d['topic_ids'])?(array)$d['topic_ids']:array())))),'country'=>isset($d['country'])?substr(sanitize_text_field($d['country']),0,64):'','location'=>isset($d['location'])?substr(sanitize_text_field($d['location']),0,191):'','availability'=>isset($d['availability'])?substr(sanitize_key($d['availability']),0,32):'','quality_score'=>isset($d['quality_score'])?min(1,max(0,(float)$d['quality_score'])):0,'authority_score'=>isset($d['authority_score'])?min(1,max(0,(float)$d['authority_score'])):0,'popularity_score'=>isset($d['popularity_score'])?max(0,(float)$d['popularity_score']):0,'freshness_at'=>$freshness,'safety_class'=>isset($d['safety_class'])?substr(sanitize_key($d['safety_class']),0,32):'general','payload'=>wp_json_encode($payload),'source_event_id'=>isset($d['source_event_id'])?substr(sanitize_text_field($d['source_event_id']),0,191):'','source_event_sequence'=>$sequence,'indexed_at'=>$now,'updated_at'=>$now);$semantic=$out;unset($semantic['object_version'],$semantic['source_event_id'],$semantic['source_event_sequence'],$semantic['indexed_at'],$semantic['updated_at']);$out['checksum']=hash('sha256',wp_json_encode($semantic));return$out;}
	private function safe_payload(array $p){$allowed=array('image_url','duration','verified_author','verified_doctor','global_doctor_rank','correction_label','retraction_label','required_entitlement','download_allowed','download_label','download_reason','source_count','language','content_type_label','ai_generated','ai_provider_label','institutional_account_class','qualification_score','experience_score','patient_verified_review_score','ethical_conduct_score','knowledge_contribution_score','responsiveness_score','profile_completeness_score','complaint_appeal_outcome_score','manipulation_resistant_engagement_score','doctor_rank_score','doctor_rank_policy_version');$c=array();foreach($allowed as $k){if(!array_key_exists($k,$p)){continue;}if('image_url'===$k){$c[$k]=$this->security->safe_resource_url($p[$k],$k);}elseif(in_array($k,array('verified_author','verified_doctor','download_allowed','ai_generated'),true)){$c[$k]=(bool)$p[$k];}elseif('global_doctor_rank'===$k||'source_count'===$k){$c[$k]=max(0,(int)$p[$k]);}elseif('doctor_rank_score'===$k){$c[$k]=min(100,max(0,(float)$p[$k]));}elseif(preg_match('/_score$/',$k)){$c[$k]=min(1,max(0,(float)$p[$k]));}else{$c[$k]=sanitize_text_field($p[$k]);}}return$c;}
	private function matches_scope(array $d,array $scope){if(empty($scope['connector'])||$d['connector_slug']!==sanitize_key($scope['connector'])){return false;}foreach(array('domain'=>'domain_name','entity_type'=>'entity_type','locale'=>'locale') as $k=>$field){if(!empty($scope[$k])&&(string)$d[$field]!== (string)$scope[$k]){return false;}}if(!empty($scope['from_version'])&&(int)$d['object_version']<(int)$scope['from_version']){return false;}if(!empty($scope['to_version'])&&(int)$d['object_version']>(int)$scope['to_version']){return false;}return true;}
	private function is_searchable(array $d){return in_array($d['state'],array('published','active','corrected','retracted'),true)&&'restricted'!==$d['visibility'];}
	private function upsert_sql($table,array $d){global $wpdb;$cols='canonical_key,connector_slug,domain_name,object_id,object_version,entity_type,locale,state,visibility,title,excerpt,normalized_title,normalized_body,canonical_url,author_key,topic_ids,country,location,availability,quality_score,authority_score,popularity_score,freshness_at,safety_class,payload,source_event_id,source_event_sequence,checksum,indexed_at,updated_at';$vals=array($d['canonical_key'],$d['connector_slug'],$d['domain_name'],$d['object_id'],$d['object_version'],$d['entity_type'],$d['locale'],$d['state'],$d['visibility'],$d['title'],$d['excerpt'],$d['normalized_title'],$d['normalized_body'],$d['canonical_url'],$d['author_key'],$d['topic_ids'],$d['country'],$d['location'],$d['availability'],$d['quality_score'],$d['authority_score'],$d['popularity_score'],$d['freshness_at'],$d['safety_class'],$d['payload'],$d['source_event_id'],$d['source_event_sequence'],$d['checksum'],$d['indexed_at'],$d['updated_at']);return $wpdb->prepare("INSERT INTO `$table` ($cols) VALUES (".implode(',',array_fill(0,30,'%s')).") ON DUPLICATE KEY UPDATE object_version=VALUES(object_version),entity_type=VALUES(entity_type),locale=VALUES(locale),state=VALUES(state),visibility=VALUES(visibility),title=VALUES(title),excerpt=VALUES(excerpt),normalized_title=VALUES(normalized_title),normalized_body=VALUES(normalized_body),canonical_url=VALUES(canonical_url),author_key=VALUES(author_key),topic_ids=VALUES(topic_ids),country=VALUES(country),location=VALUES(location),availability=VALUES(availability),quality_score=VALUES(quality_score),authority_score=VALUES(authority_score),popularity_score=VALUES(popularity_score),freshness_at=VALUES(freshness_at),safety_class=VALUES(safety_class),payload=VALUES(payload),source_event_id=VALUES(source_event_id),source_event_sequence=VALUES(source_event_sequence),checksum=VALUES(checksum),indexed_at=VALUES(indexed_at),updated_at=VALUES(updated_at)",$vals);}

	private function parity($shadow){global $wpdb;$where="state IN ('published','active','corrected','retracted') AND visibility<>'restricted'";$count=$wpdb->get_var("SELECT COUNT(*) FROM `$shadow` WHERE $where");if(null===$count||!empty($wpdb->last_error)){return new \WP_Error('file26_shadow_parity_failed','Candidate count could not be verified.');}$ctx=hash_init('sha256');$offset=0;do{$rows=$wpdb->get_results($wpdb->prepare("SELECT canonical_key,checksum FROM `$shadow` WHERE $where ORDER BY canonical_key LIMIT %d OFFSET %d",1000,$offset),ARRAY_A);if(null===$rows&&!empty($wpdb->last_error)){return new \WP_Error('file26_shadow_parity_failed','Candidate checksum rows could not be verified.');}foreach((array)$rows as $r){hash_update($ctx,$r['canonical_key'].'|'.$r['checksum']."\n");}$offset+=count((array)$rows);}while(count((array)$rows)===1000);return array('count'=>(int)$count,'checksum'=>hash_final($ctx));}

	private function cutover(array $job,array $scope,$shadow,array $parity,$token){global $wpdb;$connector=sanitize_key($scope['connector']);$documents=DB::table('documents');$nodes=DB::table('nodes');$classes=DB::table('classifications');$edges=DB::table('edges');$tombstones=DB::table('tombstones');$jobs=DB::table('jobs');$lock='file26:cutover:'.substr(hash('sha256',$connector),0,40);if('1'!==(string)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, 20)',$lock))){return new \WP_Error('file26_cutover_busy','Connector cutover is busy.');}try{$owner=$wpdb->get_var($wpdb->prepare("SELECT 1 FROM $jobs WHERE id=%d AND lock_token=%s AND status='running'",$job['id'],$token));if(!$owner){return new \WP_Error('file26_job_lock_lost','Worker lost cutover ownership.');}$scope_sql=$this->scope_sql('d',$scope,$args);$old=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $documents d WHERE d.connector_slug=%s$scope_sql",array_merge(array($connector),$args)));if(null===$old||!empty($wpdb->last_error)){return new \WP_Error('file26_cutover_read_failed','Active scope could not be measured.');}if(0===$parity['count']&&(int)$old>0&&!apply_filters('sabri_file26_empty_shadow_cutover_approved',false,$connector,$scope,(int)$old)){return new \WP_Error('file26_empty_shadow_cutover_blocked','Empty candidate cutover requires explicit approval.');}if(false===$wpdb->query('START TRANSACTION')){return new \WP_Error('file26_cutover_transaction_failed','Atomic cutover could not start.');}
			try{$scope_sql2=$this->scope_sql('d',$scope,$args2);$searchable="s.state IN ('published','active','corrected','retracted') AND s.visibility<>'restricted'";$removed=$wpdb->get_results($wpdb->prepare("SELECT d.canonical_key,d.domain_name,d.object_id,d.object_version,r.object_version AS shadow_version,r.state AS shadow_state,r.visibility AS shadow_visibility FROM $documents d LEFT JOIN `$shadow` s ON s.canonical_key=d.canonical_key AND $searchable LEFT JOIN `$shadow` r ON r.canonical_key=d.canonical_key WHERE d.connector_slug=%s$scope_sql2 AND s.canonical_key IS NULL",array_merge(array($connector),$args2)),ARRAY_A);if(null===$removed&&!empty($wpdb->last_error)){throw new \RuntimeException('Removed set failed.');}$days=max(90,min(180,(int)DB::setting('tombstone_retention_days',180)));$expires=gmdate('Y-m-d H:i:s',time()+$days*DAY_IN_SECONDS);foreach((array)$removed as $r){$shadow_version=null===$r['shadow_version']?0:(int)$r['shadow_version'];$version=max((int)$r['object_version'],$shadow_version);$reason=$shadow_version>0?(('restricted'===$r['shadow_visibility']&&in_array($r['shadow_state'],array('published','active','corrected','retracted'),true))?'restricted':sanitize_key($r['shadow_state'])):'reindex_absent';if(!$reason){$reason='reindex_absent';}$sql=$wpdb->prepare("INSERT INTO $tombstones (canonical_key,connector_slug,domain_name,object_id,object_version,reason_class,received_at,purged_at,expires_at) VALUES (%s,%s,%s,%s,%d,%s,%s,%s,%s) ON DUPLICATE KEY UPDATE reason_class=IF(VALUES(object_version)>=object_version,VALUES(reason_class),reason_class),received_at=IF(VALUES(object_version)>=object_version,VALUES(received_at),received_at),purged_at=IF(VALUES(object_version)>=object_version,VALUES(purged_at),purged_at),expires_at=IF(VALUES(object_version)>=object_version,VALUES(expires_at),expires_at),object_version=GREATEST(object_version,VALUES(object_version))",$r['canonical_key'],$connector,$r['domain_name'],$r['object_id'],$version,$reason,DB::now(),DB::now(),$expires);if(false===$wpdb->query($sql)){throw new \RuntimeException('Tombstone failed.');}}
				if($removed){$keys=array_column($removed,'canonical_key');foreach(array_chunk($keys,200) as $chunk){$ph=implode(',',array_fill(0,count($chunk),'%s'));if(false===$wpdb->query($wpdb->prepare("DELETE FROM $classes WHERE object_key IN ($ph)",$chunk))){throw new \RuntimeException('Classification purge failed.');}if(false===$wpdb->query($wpdb->prepare("DELETE FROM $edges WHERE source_key IN ($ph) OR target_key IN ($ph)",array_merge($chunk,$chunk)))){throw new \RuntimeException('Edge purge failed.');}if(false===$wpdb->query($wpdb->prepare("DELETE FROM $nodes WHERE node_key IN ($ph)",$chunk))){throw new \RuntimeException('Node purge failed.');}}}
				if(false===$wpdb->query($wpdb->prepare("DELETE d FROM $documents d WHERE d.connector_slug=%s$scope_sql2",array_merge(array($connector),$args2)))){throw new \RuntimeException('Active replacement delete failed.');}$cols='canonical_key,connector_slug,domain_name,object_id,object_version,entity_type,locale,state,visibility,title,excerpt,normalized_title,normalized_body,canonical_url,author_key,topic_ids,country,location,availability,quality_score,authority_score,popularity_score,freshness_at,safety_class,payload,source_event_id,source_event_sequence,checksum,indexed_at,updated_at';$promotable="state IN ('published','active','corrected','retracted') AND visibility<>'restricted'";if(false===$wpdb->query("INSERT INTO $documents ($cols) SELECT $cols FROM `$shadow` WHERE $promotable")){throw new \RuntimeException('Candidate promotion failed.');}$node_sql="INSERT INTO $nodes (node_key,node_type,canonical_url,visibility,state,locale,version,title,payload,updated_at) SELECT canonical_key,entity_type,canonical_url,visibility,state,locale,object_version,title,payload,updated_at FROM `$shadow` WHERE $promotable ON DUPLICATE KEY UPDATE node_type=VALUES(node_type),canonical_url=VALUES(canonical_url),visibility=VALUES(visibility),state=VALUES(state),locale=VALUES(locale),version=VALUES(version),title=VALUES(title),payload=VALUES(payload),updated_at=VALUES(updated_at)";if(false===$wpdb->query($node_sql)){throw new \RuntimeException('Node promotion failed.');}if(false===$wpdb->query('COMMIT')){throw new \RuntimeException('Cutover commit failed.');}}catch(\Throwable $e){$wpdb->query('ROLLBACK');return new \WP_Error('file26_shadow_cutover_failed','Candidate validation passed but atomic cutover failed; previous active index remains authoritative.');}
			if(function_exists('wp_cache_flush_group')){wp_cache_flush_group('sabri_file26');}else{wp_cache_flush();}$audit=$this->security->audit('shadow_reindex_cutover',array('object_type'=>'connector','object_key'=>$connector,'metadata'=>array('job_uuid'=>$job['job_uuid'],'candidate_count'=>$parity['count'],'candidate_checksum'=>$parity['checksum'],'previous_count'=>(int)$old,'mode'=>$scope['mode'])));if(is_wp_error($audit)){return new \WP_Error('file26_required_audit_failed','Shadow cutover persisted but required audit evidence failed.',array('status'=>500,'mutation_persisted'=>true));}do_action('sabri_file26_event','SearchIndexShadowCutoverCompleted',array('connector'=>$connector,'job_uuid'=>$job['job_uuid'],'count'=>$parity['count'],'checksum'=>$parity['checksum']));return true;
		}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}}

	private function fail(array $job,$token,$code,$attempts,$cause=null,$drop_on_dead=true){global $wpdb;$status=$attempts>=8?'dead_letter':'retry';$retry=min(DAY_IN_SECONDS,(int)pow(2,min(10,$attempts))*60);$updated=$wpdb->update(DB::table('jobs'),array('status'=>$status,'error_code'=>sanitize_key($code),'lock_token'=>null,'available_at'=>gmdate('Y-m-d H:i:s',time()+$retry),'finished_at'=>'dead_letter'==$status?DB::now():null,'updated_at'=>DB::now()),array('id'=>$job['id'],'lock_token'=>$token,'status'=>'running'));if(1!==(int)$updated){return new \WP_Error('file26_job_failure_write_failed','Shadow failure state could not be persisted.');}if('dead_letter'==$status&&$drop_on_dead){$shadow=$this->shadow_table($job['job_uuid']);$wpdb->query("DROP TABLE IF EXISTS `$shadow`");}return new \WP_Error('file26_shadow_reindex_failed','Shadow reindex failed and moved to governed retry/dead-letter state.',array('status'=>503,'error_code'=>sanitize_key($code),'job_status'=>$status,'cause'=>is_wp_error($cause)?$cause->get_error_code():null));}
	private function scope(array $s){$out=array();foreach(array('domain','entity_type','locale','mode','reason','from_version','to_version') as $k){if(!array_key_exists($k,$s)||is_array($s[$k])||is_object($s[$k])){continue;}$out[$k]=in_array($k,array('from_version','to_version'),true)?max(0,(int)$s[$k]):substr(('mode'==$k||'domain'==$k||'entity_type'==$k)?sanitize_key($s[$k]):sanitize_text_field($s[$k]),0,191);}return$out;}
	private function scope_sql($alias,array $scope,&$args){$args=array();$sql='';foreach(array('domain'=>'domain_name','entity_type'=>'entity_type','locale'=>'locale') as $k=>$column){if(!empty($scope[$k])){$sql.=" AND $alias.$column=%s";$args[]=$scope[$k];}}if(!empty($scope['from_version'])){$sql.=" AND $alias.object_version>=%d";$args[]=(int)$scope['from_version'];}if(!empty($scope['to_version'])){$sql.=" AND $alias.object_version<=%d";$args[]=(int)$scope['to_version'];}return$sql;}
	private function shadow_table($uuid){global $wpdb;return $wpdb->prefix.'f26_shadow_'.substr(hash('sha256',(string)$uuid),0,20);}
	private function table_exists($table){global $wpdb;$v=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)));return empty($wpdb->last_error)&&$v===$table;}
	public function health_extension($extra){global $wpdb;$extra=is_array($extra)?$extra:array();$jobs=DB::table('jobs');$counts=$wpdb->get_results("SELECT status,COUNT(*) AS c FROM $jobs WHERE job_type='shadow_reindex_v2' GROUP BY status",ARRAY_A);$map=array();foreach((array)$counts as $r){$map[$r['status']]=(int)$r['c'];}$extra['shadow_reindex']=array('mode'=>'isolated_blue_green','jobs'=>$map,'snapshot_contract'=>'final batch requires searchable snapshot_count and SHA-256 of sorted canonical_key|checksum lines; restrictive source rows are retained only as cutover revocation evidence','old_index_available_until_atomic_cutover'=>true);return$extra;}
}
